spec = {"prefill": 3, "decode": 8}
actual = {"prefill": ["p1", "p2", "p3"], "decode": ["d1", "d2", "d3", "d4", "d5", "d6"]}

def reconcile(spec, actual):
    actions = []
    for role in ("prefill", "decode"):
        have, want = len(actual[role]), spec[role]
        if have < want:
            actions += [f"create {role} pod #{i}" for i in range(have + 1, want + 1)]
        elif have > want:
            actions += [f"delete {p}" for p in actual[role][want:]]
    return actions or ["nothing to do"]

for a in reconcile(spec, actual):
    print(a)
actual["decode"] += ["d7", "d8"]
print("다음 바퀴:", reconcile(spec, actual))
